def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    for c in range(w):
        if grid[-1][c] != 5: continue
        seeds=[(r,grid[r][c]) for r in range(h) if grid[r][c]!=0]
        for r in range(h):
            if out[r][c]==0:
                # nearest colored point in this column; ties go to lower seed
                _, color=min(seeds,key=lambda x:(abs(x[0]-r),-x[0]))
                out[r][c]=color
    return out
