        if grid[-1][c] != 5: continue
        seeds=[(r,grid[r][c]) for r in range(h-1) if grid[r][c]!=0]
        if not seeds: continue
        # Fill each gap with the color of the lower endpoint; leading gap uses first seed.
        first_r,first_color=seeds[0]
        for r in range(first_r):
            if out[r][c]==0: out[r][c]=first_color
        for (r1,_),(r2,color) in zip(seeds,seeds[1:]):
            for r in range(r1+1,r2):
                if out[r][c]==0: out[r][c]=color
        last_r=seeds[-1][0]
        for r in range(last_r+1,h):
            if out[r][c]==0: out[r][c]=5
    return out
